/**
 * Spotify for Artists Stats Display Module
 * 
 * Fetches data from spotify_stats.json (generated by scraper) and displays it on the page
 * 
 * Security: Uses shared security utilities for consistent sanitization
 * Dependencies: security-utils.js must be loaded first
 */

const SPOTIFY_STATS_URL = '../../data/spotify_stats.json';
const REFRESH_INTERVAL = 5 * 60 * 1000; // 5 minutes

class SpotifyArtistsStatsDisplay {
  constructor() {
    this.stats = null;
    this.container = null;
  }

  /**
   * Escape HTML using shared utilities with fallback
   */
  escapeHtml(text) {
    if (window.SecurityUtils && window.SecurityUtils.escapeHtml) {
      return window.SecurityUtils.escapeHtml(text);
    }
    // Consistent map-based fallback
    if (typeof text !== 'string') text = String(text);
    return text.replace(/[&<>"']/g, char => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#x27;'
    }[char]));
  }

  /**
   * Initialize the stats display
   */
  async init(containerId = 'spotify-artists-stats') {
    this.container = document.getElementById(containerId);
    
    if (!this.container) {
      console.warn(`Container #${containerId} not found. Spotify Artists stats will not be displayed.`);
      return;
    }

    // Load and display stats
    await this.loadStats();

    // Refresh periodically
    setInterval(() => this.loadStats(), REFRESH_INTERVAL);
  }

  /**
   * Load stats from JSON file
   */
  async loadStats() {
    try {
      const response = await fetch(SPOTIFY_STATS_URL);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      this.stats = await response.json();
      this.render();
      
    } catch (error) {
      console.error('Failed to load Spotify Artists stats:', error);
      this.renderError();
    }
  }

  /**
   * Format a number with commas
   */
  formatNumber(num) {
    if (num === null || num === undefined) return 'N/A';
    return num.toLocaleString();
  }

  /**
   * Format relative time
   */
  formatRelativeTime(isoString) {
    if (!isoString) return 'Unknown';
    
    try {
      const date = new Date(isoString);
      const now = new Date();
      const diffMs = now - date;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return 'Just now';
      if (diffMins < 60) return `${diffMins} minute${diffMins !== 1 ? 's' : ''} ago`;
      if (diffHours < 24) return `${diffHours} hour${diffHours !== 1 ? 's' : ''} ago`;
      return `${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;
    } catch (e) {
      return 'Unknown';
    }
  }

  /**
   * Render the stats display
   */
  render() {
    if (!this.stats || !this.container) return;

    const { listeners, streams, followers, top_cities, scraped_at } = this.stats;

    this.container.innerHTML = `
      <div class="spotify-artists-stats">
        <div class="stats-header">
          <h2>📊 Spotify for Artists Stats</h2>
          <p class="stats-timestamp">Updated: ${this.formatRelativeTime(scraped_at)}</p>
        </div>

        <div class="stats-grid">
          <!-- Main Metrics -->
          <div class="stat-card">
            <div class="stat-icon">🎧</div>
            <div class="stat-value">${this.formatNumber(listeners)}</div>
            <div class="stat-label">Current Listeners</div>
          </div>

          <div class="stat-card">
            <div class="stat-icon">▶️</div>
            <div class="stat-value">${this.formatNumber(streams)}</div>
            <div class="stat-label">Total Streams</div>
          </div>

          <div class="stat-card">
            <div class="stat-icon">👥</div>
            <div class="stat-value">${this.formatNumber(followers)}</div>
            <div class="stat-label">Followers</div>
          </div>
        </div>

        ${this.renderTopCities(top_cities)}
      </div>
    `;
  }

  /**
   * Render top cities section
   */
  renderTopCities(cities) {
    if (!cities || cities.length === 0) {
      return '';
    }

    const citiesList = cities.map((city, index) => `
      <div class="city-item">
        <span class="city-rank">${index + 1}.</span>
        <span class="city-name">${this.escapeHtml(city.city)}</span>
        <span class="city-listeners">${this.formatNumber(city.listeners)} listeners</span>
      </div>
    `).join('');

    return `
      <div class="stats-section">
        <h3>🌍 Top Cities</h3>
        <div class="cities-list">
          ${citiesList}
        </div>
      </div>
    `;
  }

  /**
   * Render error message
   */
  renderError() {
    if (!this.container) return;

    this.container.innerHTML = `
      <div class="spotify-artists-stats error">
        <div class="error-message">
          <span class="error-icon">⚠️</span>
          <p>Unable to load Spotify Artists stats. Please try again later.</p>
        </div>
      </div>
    `;
  }
}

// Initialize when DOM is ready
function initializeSpotifyStats() {
  const statsDisplay = new SpotifyArtistsStatsDisplay();
  statsDisplay.init();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeSpotifyStats);
} else {
  initializeSpotifyStats();
}

// Export for manual initialization if needed
if (typeof module !== 'undefined' && module.exports) {
  module.exports = SpotifyArtistsStatsDisplay;
}
